import pytest

from bedrock_protocol import v975, v1001

PREFIX = bytes(32)

# generated by gophertunnel 0a2ecd5:
# NewBitset(130) with bits 0, 1 and 129 set, written by protocol.NewWriter(...).Bitset
WIDE = bytes.fromhex("83808080808080808080808080808080808008")

# generated by gophertunnel 0a2ecd5:
# NewBitset(65) with no bit set
EMPTY = bytes.fromhex("00")

# generated by gophertunnel 0a2ecd5:
# NewBitset(65) with bit 64 set
TOP = bytes.fromhex("80808080808080808002")

# generated by gophertunnel 0a2ecd5:
# NewBitset(65) with bits 0, 34 and 64 set
SPREAD = bytes.fromhex("81808080c08080808002")

# generated by gophertunnel 0a2ecd5:
# NewBitset(65) with every bit set
FULL = bytes.fromhex("ffffffffffffffffff03")

# generated by gophertunnel 0a2ecd5:
# NewBitset(65) with bit 6 set
BIT_6 = bytes.fromhex("40")

# generated by gophertunnel 0a2ecd5:
# NewBitset(65) with bit 7 set
BIT_7 = bytes.fromhex("8001")

WIDE_VALUE = (1 << 129) | 0b11

BODYLESS = [
    pytest.param(0, EMPTY, id="empty"),
    pytest.param(1 << 64, TOP, id="bit-64"),
    pytest.param(1 << 6, BIT_6, id="bit-6"),
    pytest.param(1 << 7, BIT_7, id="bit-7"),
]

GATED = [
    pytest.param((1 << 64) | (1 << 34) | 1, SPREAD, id="spread"),
    pytest.param((1 << 65) - 1, FULL, id="full"),
]

REJECTS = [
    pytest.param("80808080808080808004", id="bit-past-the-width"),
    pytest.param("80808080808080808082", id="continuation-on-the-last-group"),
    pytest.param("8080", id="frame-ends-mid-value"),
]


@pytest.mark.parametrize("version", [v975, v1001], ids=lambda version: version.__name__.rpartition(".")[2])
def test_a_130_bit_bitset_encodes_to_its_golden(version):
    assert bytes(version.ActorDataFlagComponent(value=WIDE_VALUE)) == WIDE


@pytest.mark.parametrize("version", [v975, v1001], ids=lambda version: version.__name__.rpartition(".")[2])
def test_a_130_bit_bitset_decodes_from_its_golden(version):
    assert version.ActorDataFlagComponent.from_bytes(WIDE) == version.ActorDataFlagComponent(value=WIDE_VALUE)


@pytest.mark.parametrize(("value", "golden"), BODYLESS + GATED)
def test_a_65_bit_bitset_encodes_to_its_golden(value, golden):
    assert bytes(v1001.PlayerAuthInputPacket(input_data=value))[32 : 32 + len(golden)] == golden


@pytest.mark.parametrize(("value", "golden"), BODYLESS)
def test_a_65_bit_bitset_decodes_from_its_golden(value, golden):
    packet = v1001.PlayerAuthInputPacket.from_bytes(PREFIX + golden + bytes(52))
    assert packet == v1001.PlayerAuthInputPacket(input_data=value)


def test_a_bit_past_the_declared_width_cannot_be_assigned():
    with pytest.raises(TypeError, match="cannot hold"):
        v1001.PlayerAuthInputPacket(input_data=1 << 65)


@pytest.mark.parametrize("wire", REJECTS)
def test_decode_rejects_a_65_bit_bitset_that_is_not_one(wire):
    with pytest.raises(ValueError, match="at byte"):
        v1001.PlayerAuthInputPacket.from_bytes(PREFIX + bytes.fromhex(wire))
